import os
import sys

from gameoflife import BOARD_T

os.environ["PYGAME_HIDE_SUPPORT_PROMPT"] = "hide"
import pygame  # noqa: E402


class GameOfLifeDisplay:
    def __init__(self, board: BOARD_T, width: int = 800):
        pygame.init()
        self.board = board
        self.rows = len(board)
        self.cols = len(board[0]) if self.rows > 0 else 0
        self.cell_size = width // self.cols
        self.width = self.cols * self.cell_size
        self.height = self.rows * self.cell_size
        self.screen = pygame.display.set_mode((self.width, self.height))
        pygame.display.set_caption("Conway's Game of Life Neural Network")
        self.update_board(board)

    def draw_grid(self) -> None:
        for x in range(0, self.width, self.cell_size):
            pygame.draw.line(self.screen, (200, 200, 200), (x, 0), (x, self.height))
        for y in range(0, self.height, self.cell_size):
            pygame.draw.line(self.screen, (200, 200, 200), (0, y), (self.width, y))

    def update_board(self, new_board: BOARD_T) -> None:
        self._process_quitting()

        self.board = new_board
        self.screen.fill((255, 255, 255))
        self.draw_grid()

        for row in range(self.rows):
            for col in range(self.cols):
                if self.board[row][col] == 1:
                    pygame.draw.rect(
                        self.screen,
                        (0, 0, 0),
                        (
                            col * self.cell_size,
                            row * self.cell_size,
                            self.cell_size,
                            self.cell_size,
                        ),
                    )

        pygame.display.flip()

    @staticmethod
    def _process_quitting() -> None:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

""" Trie boiler plate code Supported by standard GitHub tools and verified by Alex Badia  """

class TrieNode:
  def __init__(self):
    self.children = {}
    self.is_end_of_word = False

class Trie:
  def __init__(self):
    self.root = TrieNode()

  def insert(self, words):
    node = self.root
    for word in words:
      if word not in node.children:
        node.children[word] = TrieNode()
      node = node.children[word]
    node.is_end_of_word = True

  def search(self, words):
    node = self.root
    for word in words:
      if word not in node.children:
        return False
      node = node.children[word]

    return node.is_end_of_word

  def count_paths(self, node=None):
    if node is None:
      node = self.root
    count = 1 if node.is_end_of_word else 0
    for child in node.children.values():
      count += self.count_paths(child)
    return count

  def print_trie(self, node=None, word=""):
    if node is None:
      node = self.root
    if node.is_end_of_word:
      print(word)
    for k, v in node.children.items():
      self.print_trie(v, word + " " + k)

  def pretty_print_trie(self, filename):
    with open(filename, 'w') as file:
      self._pretty_print_trie_helper(self.root, "", file)

  def _pretty_print_trie_helper(self, node, word, file):
    if node.is_end_of_word:
      file.write(word + '\n')
    for k, v in node.children.items():
      self._pretty_print_trie_helper(v, word + " " + str(k), file)

GRID_SIZE = 300
GRID_SERIAL = 8772

def calculate_power(x, y):
    rack_id = x + 10
    power_level = rack_id * y
    power_level += GRID_SERIAL
    power_level *= rack_id
    power_level = power_level // 100 % 10
    return power_level - 5

def init_grid():
    grid = [[0 for _ in range(GRID_SIZE)] for _ in range(GRID_SIZE)]
    for y in range(GRID_SIZE):
        for x in range(GRID_SIZE):
            grid[y][x] = calculate_power(x, y)
    return grid

# thanks chatgpt, for pointing out the summed-area table calculation
def init_summed_area_table(grid):
    summed_area = [[0 for _ in range(GRID_SIZE + 1)] for _ in range(GRID_SIZE + 1)]
    for y in range(1, GRID_SIZE + 1):
        for x in range(1, GRID_SIZE + 1):
            summed_area[y][x] = grid[y - 1][x - 1] \
                              + summed_area[y - 1][x] \
                              + summed_area[y][x - 1] \
                              - summed_area[y - 1][x - 1]
    return summed_area

def get_submatrix_sum(x1, y1, x2, y2):
    return summed_area[y2 + 1][x2 + 1] \
         - summed_area[y1][x2 + 1] \
         - summed_area[y2 + 1][x1] \
         + summed_area[y1][x1]


grid = init_grid()
summed_area = init_summed_area_table(grid)

def part1(size):
    max_power = float('-inf')
    best_coords = (0, 0)
    for y in range(GRID_SIZE - size + 1):
        for x in range(GRID_SIZE - size + 1):
            submatrix_sum = get_submatrix_sum(x, y, x + size - 1, y + size - 1)
            if submatrix_sum > max_power:
                max_power = submatrix_sum
                best_coords = (x, y)
    return (best_coords, max_power)


def part2():
    max_power = float('-inf')
    best_coords = (0, 0)
    best_size = 0

    for size in range(1, GRID_SIZE + 1):
        coords, power = part1(size)
        if power > max_power:
            max_power = power
            best_coords = coords
            best_size = size

    return (best_coords, best_size)


print("Part 1: ", part1(3))
print("Part 2: ", part2())

