    }


@magik_eval
def api_call(
    url: str,
    payload: dict,
    headers: dict = None,
    output_to_test=None,
):
    payload["output_to_test"] = output_to_test
    response = requests.post(url, json=payload, headers=headers)
    result = response.json().get("result")
    reason = response.json().get("reason")

    return {
        "result": result,
        "reason": reason,
    }


@magik_eval
def levenshtein_distance_below_threshold(
    compare_against: str,
    threshold: float,
    output_to_test=None,
):
    distance = levenshtein_distance(output_to_test, compare_against)
    result = distance < threshold
    reason = (
        f"levenshtein distance is {distance} and is below threshold {threshold}"
        if result
        else f"levenshtein distance is {distance} and is not below threshold {threshold}"
    )
    return {
        "result": result,
        "reason": reason,
    }


@magik_eval
def levenshtein_distance_above_threshold(
    compare_against: str,
    threshold: float,
    output_to_test=None,
):
    distance = levenshtein_distance(output_to_test, compare_against)
    result = distance > threshold
    reason = (
        f"levenshtein distance is {distance} and is above threshold {threshold}"
        if result
        else f"levenshtein distance is {distance} and is not above threshold {threshold}"
    )
    return {
        "result": result,
        "reason": reason,
    }


@magik_eval
def _and(functions: list[Any], output_to_test=None):
    for fn in functions:
        fn_res = fn(output_to_test)
        result = fn_res["result"]
        if result == False:
            reason = fn_res["reason"]
            return {
                "result": result,
                "reason": f"Function {fn.__name__} failed with reason: {reason}",
            }
    return {"result": True, "reason": "All functions returned True"}


@magik_eval
def _or(functions: list[Any], output_to_test=None):
    for fn in functions:
        fn_res = fn(output_to_test)
        result = fn_res["result"]
        if result == True:
            reason = fn_res["reason"]
            return {
                "result": result,
                "reason": f"Function {fn.__name__} passed with reason: {reason}",
            }
    return {"result": True, "reason": "All functions returned False"}

"""
    Abstract Factory
    ----------------
    This pattern provides an interface for creating families of related or dependent objects without
    specifying their concrete classes. It allows the creation of object hierarchies that are specific
    to a particular implementation or platform.

    - All descriptions and comments Designed via basic programming aids and GitHub Copilot
"""

from abc import ABC, abstractmethod  # Abstract Base Class

class Button(ABC):
    """
        Abstract Base Class for Button
    """
    @abstractmethod
    def render(self) -> None:
        pass

class WindowsButton(Button):
    """
        Concrete Class for WindowsButton
    """
    def render(self) -> None:
        print("Windows Button")

class MacButton(Button):
    """
        Concrete Class for MacButton
    """
    def render(self) -> None:
        print("Mac Button")

class Checkbox(ABC):
    """
        Abstract Base Class for Checkbox
    """
    @abstractmethod
    def render(self) -> None:
        pass

class WindowsCheckbox(Checkbox):
    """
        Concrete Class for WindowsCheckbox
    """
    def render(self) -> None:
        print("Windows Checkbox")

class MacCheckbox(Checkbox):
    """
        Concrete Class for MacCheckbox
    """
    def render(self) -> None:
        print("Mac Checkbox")

class GUIFactory(ABC):
    """
        Abstract Base Class for GUIFactory
    """
    @abstractmethod
    def create_button(self) -> Button:
        pass

    @abstractmethod
    def create_checkbox(self) -> Checkbox:
        pass

class WindowsFactory(GUIFactory):
    """
        Concrete Factory 1
    """
    def create_button(self) -> Button:
        return WindowsButton()

    def create_checkbox(self) -> Checkbox:
        return WindowsCheckbox()

class MacFactory(GUIFactory):
    """
        Concrete Factory 2
    """
    def create_button(self) -> Button:
        return MacButton()

    def create_checkbox(self) -> Checkbox:
        return MacCheckbox()

# Client
class Application:
    def __init__(self, factory: GUIFactory):
        self.factory = factory

    def create_ui(self) -> None:
        button = self.factory.create_button()
        checkbox = self.factory.create_checkbox()
        button.render()
        checkbox.render()


if __name__ == "__main__":
    app = Application(WindowsFactory())
    app.create_ui()
    app = Application(MacFactory())
    app.create_ui()

"""
    Output:
    -------
    Windows Button
    Windows Checkbox
    Mac Button
    Mac Checkbox
"""

class Solution:
    def equationsPossible(self, equations: List[str]) -> bool:
        uf = UnionFind(26)
        check_later = []
        for e in equations:
            if e[1] == '=':
                uf.union(ord(e[0])- ord('a'), ord(e[-1])- ord('a'))
            else:
                check_later.append(e)
        for ie in check_later:
            p0, p1 = uf.find(ord(ie[0])- ord('a')), uf.find(ord(ie[-1])- ord('a'))
            if p0 == p1:
                return False
        return True


class UnionFind:
    def __init__(self, n):
        self.parent = [i for i in range(n)]
        self.rank = [1]*n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        pu = self.find(u)
        pv = self.find(v)
        if pu == pv:
            return False
        if self.rank[pu] > self.rank[pv]:
            self.parent[pv] = pu
        elif self.rank[pu] < self.rank[pv]:
            self.parent[pu] = pv
        else:
            self.rank[pv] += 1
            self.parent[pu] = pv
        return True
